function deskList(key) {
  checkKey_(key);
  const out = [], it = deskRoot_().getFolders();
  while (it.hasNext()) {
    const f = it.next(), meta = deskJson_(f, '案件.json'); if (!meta) continue;
    const files = []; const fi = f.getFiles(); while (fi.hasNext()) { const x = fi.next(); files.push(x.getName()); }
    let st = deskStatus_(f), before = null, after = null;
    if (meta.type === 'skin') { try { before = JSON.parse(deskTxt_(f, 'before.txt') || 'null'); } catch (e) {} try { after = JSON.parse(deskTxt_(f, 'after.txt') || 'null'); } catch (e) {} if (st === 'wait' && !after) st = 'pre'; }
    if (meta.type === 'inbody' && st !== 'sent') st = ibFull_(ibNums_((deskJson_(f, '草稿.json') || {}).after)) ? 'draft' : 'pre';
    out.push({id: f.getId(), meta: meta, status: st, files: files.filter(function (n) { return !/\.json$/.test(n); }), before: before, after: after,
      draft: (st === 'draft' || meta.type === 'inbody') ? deskJson_(f, '草稿.json') : null, sent: st === 'sent' ? deskJson_(f, '已送出.json') : null, url: f.getUrl()});
  }
  return out.sort(function (a, b) { return a.meta.created < b.meta.created ? 1 : -1; }).slice(0, 40);
}
function deskList(key) {
  checkKey_(key);
  const out = [], it = deskRoot_().getFolders();
  while (it.hasNext()) {
    const f = it.next(), meta = deskJson_(f, '案件.json'); if (!meta) continue;
    const files = []; const fi = f.getFiles(); while (fi.hasNext()) { const x = fi.next(); files.push(x.getName()); }
    let st = deskStatus_(f), before = null, after = null, oils = null;
    if (meta.type === 'skin') { try { before = JSON.parse(deskTxt_(f, 'before.txt') || 'null'); } catch (e) {} try { after = JSON.parse(deskTxt_(f, 'after.txt') || 'null'); } catch (e) {} if (st === 'wait') st = !before ? 'collect' : !after ? 'pre' : 'wait'; }
    if (meta.type === 'inbody' && st !== 'sent') st = ibFull_(ibNums_((deskJson_(f, '草稿.json') || {}).after)) ? 'draft' : 'pre';
    if ((meta.type === 'soul' || meta.type === 'oil100') && st === 'wait' && files.indexOf('ready.txt') < 0) st = 'collect'; // 島主還在交材料，按「交給 AI 整理」才開始
    if (meta.type === 'oil100') { try { oils = JSON.parse(deskTxt_(f, 'oils.txt') || 'null'); } catch (e) {} }
    let skdraft = null; if (meta.type === 'skin' && st !== 'sent') { try { skdraft = JSON.parse(deskTxt_(f, 'skdraft.txt') || 'null'); } catch (e) {} } // 皮膚檢測填到一半的進度
    out.push({id: f.getId(), meta: meta, status: st, files: files.filter(function (n) { return !/\.json$/.test(n); }), before: before, after: after, oils: oils, skdraft: skdraft,
      draft: deskJson_(f, '草稿.json'), sent: st === 'sent' ? deskJson_(f, '已送出.json') : null, url: f.getUrl()});
