function deskRetype(key, id, type) {
  checkKey_(key);
  const f = deskCase_(id), meta = deskJson_(f, '案件.json'), t = DESK_TYPES[type];
  if (!t) throw new Error('沒有這個類型');
  if (deskJson_(f, '已送出.json')) throw new Error('已經送出的案件不能改類型');
  meta.type = type; meta.typeName = t.name; deskPut_(f, '案件.json', meta);
  ['草稿.json', '處理中.json', '錯誤.txt', 'ready.txt'].forEach(function (n) { const x = f.getFilesByName(n); while (x.hasNext()) x.next().setTrashed(true); });
  if (type === 'inbody') deskPut_(f, '草稿.json', {before: [], after: []});
  return {ok: true};
}

function deskInbody(key, id, arr) {
  checkKey_(key);
  const f = deskCase_(id), meta = deskJson_(f, '案件.json');
  if (meta.type !== 'inbody') throw new Error('這不是 InBody 案件');
  if (deskJson_(f, '已送出.json')) throw new Error('這個案件已經送出過了');
  const d = deskJson_(f, '草稿.json') || {}; d.after = ibNums_(arr);
  if (!ibFull_(d.after)) throw new Error('療程後 6 個數字要填完');
  deskPut_(f, '草稿.json', d);
  return {ok: true};
}
function deskInbody(key, id, arr, which) {
  checkKey_(key);
  const f = deskCase_(id), meta = deskJson_(f, '案件.json');
  if (meta.type !== 'inbody') throw new Error('這不是 InBody 案件');
  if (deskJson_(f, '已送出.json')) throw new Error('這個案件已經送出過了');
  const d = deskJson_(f, '草稿.json') || {}, k = which === 'before' ? 'before' : 'after'; d[k] = ibNums_(arr);
